const http = require('http');
const https = require('https');
const { URL } = require('url');
const crypto = require('crypto');
const net = require('net');

// Webhook delivery service for CI/CD pipeline notifications
const BLOCKED_RANGES = [
  { start: '10.0.0.0', end: '10.255.255.255' },
  { start: '172.16.0.0', end: '172.31.255.255' },
  { start: '192.168.0.0', end: '192.168.255.255' },
  { start: '127.0.0.0', end: '127.255.255.255' },
  { start: '169.254.0.0', end: '169.254.255.255' },
  { start: '0.0.0.0', end: '0.255.255.255' }
];

function ipToLong(ip) {
  const parts = ip.split('.');
  if (parts.length !== 4) return -1;
  let result = 0;
  for (let i = 0; i < 4; i++) {
    const octet = parseInt(parts[i], 10);
    if (isNaN(octet) || octet < 0 || octet > 255) return -1;
    result = (result * 256) + octet;
  }
  return result;
}

function isBlockedIP(ip) {
  const ipLong = ipToLong(ip);
  if (ipLong === -1) return true; // block unparseable
  for (const range of BLOCKED_RANGES) {
    const start = ipToLong(range.start);
    const end = ipToLong(range.end);
    if (ipLong >= start && ipLong <= end) return true;
  }
  return false;
}

async function resolveHostname(hostname) {
  const dns = require('dns');
  return new Promise((resolve, reject) => {
    dns.resolve4(hostname, (err, addresses) => {
      if (err) reject(err);
      else resolve(addresses);
    });
  });
}

function validateWebhookUrl(urlString) {
  // Normalize the URL string before parsing
  const normalized = urlString.trim();

  let parsed;
  try {
    parsed = new URL(normalized);
  } catch (e) {
    return { valid: false, error: 'Invalid URL format' };
  }

  // Only allow http and https
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return { valid: false, error: 'Only HTTP(S) allowed' };
  }

  // Block credentials in URL
  if (parsed.username || parsed.password) {
    return { valid: false, error: 'Credentials not allowed in URL' };
  }

  // Validate port
  const port = parsed.port ? parseInt(parsed.port, 10) : (parsed.protocol === 'https:' ? 443 : 80);
  if (port < 1 || port > 65535) {
    return { valid: false, error: 'Invalid port' };
  }

  // Check for IP address in hostname
  const hostname = parsed.hostname;
  if (net.isIP(hostname)) {
    if (isBlockedIP(hostname)) {
      return { valid: false, error: 'Blocked IP range' };
    }
  }

  return { valid: true, parsed, hostname, port };
}

async function deliverWebhook(urlString, payload, secret) {
  const validation = validateWebhookUrl(urlString);
  if (!validation.valid) {
    return { success: false, error: validation.error };
  }

  const { hostname, port } = validation;

  // DNS resolution check for non-IP hostnames
  if (!net.isIP(hostname)) {
    try {
      const addresses = await resolveHostname(hostname);
      for (const addr of addresses) {
        if (isBlockedIP(addr)) {
          return { success: false, error: 'Hostname resolves to blocked IP' };
        }
      }
    } catch (e) {
      return { success: false, error: 'DNS resolution failed' };
    }
  }

  // Sign the payload
  const body = JSON.stringify(payload);
  const signature = crypto
    .createHmac('sha256', secret)
    .update(body)
    .digest('hex');

  // Make the request using the ORIGINAL url string for the request
  // This preserves any path/query parameters exactly as specified
  const requestUrl = new URL(urlString.trim());

  const options = {
    hostname: requestUrl.hostname,
    port: requestUrl.port || (requestUrl.protocol === 'https:' ? 443 : 80),
    path: requestUrl.pathname + requestUrl.search,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
      'X-Webhook-Signature': `sha256=${signature}`,
      'X-Webhook-Timestamp': Date.now().toString()
    },
    timeout: 10000
  };

  return new Promise((resolve) => {
    const transport = requestUrl.protocol === 'https:' ? https : http;
    const req = transport.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({ success: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode });
      });
    });
    req.on('error', (e) => resolve({ success: false, error: e.message }));
    req.on('timeout', () => { req.destroy(); resolve({ success: false, error: 'Timeout' }); });
    req.write(body);
    req.end();
  });
}

// Webhook registration with rate limiting
const registrations = new Map();
const deliveryLog = new Map();

function registerWebhook(userId, urlString, events) {
  if (!userId || typeof userId !== 'string') return { error: 'Invalid user' };
  if (!urlString || typeof urlString !== 'string') return { error: 'Invalid URL' };
  if (!Array.isArray(events) || events.length === 0) return { error: 'Invalid events' };

  const validation = validateWebhookUrl(urlString);
  if (!validation.valid) return { error: validation.error };

  const id = crypto.randomUUID();
  const webhook = {
    id,
    userId,
    url: urlString,
    events,
    secret: crypto.randomBytes(32).toString('hex'),
    createdAt: Date.now(),
    active: true
  };

  if (!registrations.has(userId)) registrations.set(userId, []);
  registrations.get(userId).push(webhook);

  return { id, secret: webhook.secret };
}

async function triggerEvent(eventType, eventData) {
  const results = [];
  for (const [userId, webhooks] of registrations) {
    for (const webhook of webhooks) {
      if (!webhook.active) continue;
      if (!webhook.events.includes(eventType)) continue;

      const payload = {
        event: eventType,
        data: eventData,
        webhookId: webhook.id,
        timestamp: Date.now()
      };

      const result = await deliverWebhook(webhook.url, payload, webhook.secret);
      results.push({ webhookId: webhook.id, ...result });

      // Log delivery
      if (!deliveryLog.has(webhook.id)) deliveryLog.set(webhook.id, []);
      deliveryLog.get(webhook.id).push({
        timestamp: Date.now(),
        success: result.success,
        status: result.status || null
      });
    }
  }
  return results;
}

module.exports = { registerWebhook, triggerEvent, deliverWebhook, validateWebhookUrl };
